import json
from hypothesis import strategies as st

MOD = 10**9 + 7

@st.composite
def gen(draw):
    n = draw(st.integers(1, 10))
    pool = st.one_of(
        st.integers(0, 4),
        st.sampled_from([0, 1, 2, 3, 99999, 100000]),
    )
    nums = draw(st.lists(pool, min_size=n, max_size=n))
    return json.dumps(nums)

def validate(inp):
    try:
        nums = json.loads(inp)
    except Exception:
        return False
    if not isinstance(nums, list):
        return False
    if not (1 <= len(nums) <= 10**5):
        return False
    for x in nums:
        if not isinstance(x, int) or isinstance(x, bool):
            return False
        if not (0 <= x <= 10**5):
            return False
    return True

def ref(inp):
    nums = json.loads(inp)
    n = len(nums)
    total = 0
    # Brute force over all non-empty index subsets (subsequences by index).
    for mask in range(1, 1 << n):
        idx = [i for i in range(n) if (mask >> i) & 1]
        ok = True
        for k in range(len(idx) - 1):
            if abs(nums[idx[k]] - nums[idx[k + 1]]) != 1:
                ok = False
                break
        if ok:
            total += sum(nums[i] for i in idx)
    return json.dumps(total % MOD)
